NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Amos'

CHAPTERS = {
    1: {
        1: 'Die Worte des Amos, der unter den Viehhirten von Thekoa war, die er geschaut hat über Israel in den Tagen des Ussiah, König von Jehudah, und in den Tagen von Jerobeam, dem Sohne des Joasch, des Königs von Israel, zwei Jahre vor dem Erdbeben.',
        2: 'Und er sprach: Jehovah brüllt von Zion, und aus Jerusalem gibt Er Seine Stimme hervor. Und der Hirten Auen trauern, und das Haupt des Karmel verdorrt.',
        3: 'So spricht Jehovah: Ob dreier Übertretungen Damasks und ob vierer wende Ich es nicht zurück: Darum, daß sie Gilead mit eisernen Dreschwagen gedroschen.',
        4: 'Und Ich sende ein Feuer in Chasaels Haus, daß es Ben-Hadads Paläste auffresse.',
        5: 'Und Damasks Riegel zerbreche Ich und rotte aus die Bewohner der Talebene Aven, und den, der das Zepter hält aus Beth-Eden, und in Verbannung zieht Arams Volk nach Kir! spricht Jehovah.',
        6: 'So spricht Jehovah: Ob dreier Übertretungen Gazahs und ob vierer wende Ich es nicht zurück: Darum, daß sie eine Vollzahl der Weggeführten haben weggeführt, um sie an Edom zu überantworten.',
        7: 'Und Ich sende ein Feuer in Gazahs Mauern, daß es seine Paläste auffresse.',
        8: 'Und Ich rotte aus den Bewohner aus Aschdod und den, der das Zepter hält aus Aschkalon, und wende zurück Meine Hand wider Ekron, und sie sollen vergehen, der Überrest der Philister, spricht der Herr, Jeho- vah.',
        9: 'Also spricht Jehovah: Ob dreier Übertretungen Zors und ob vierer wende Ich es nicht zurück: Darum, daß sie die Vollzahl der Weggeführten an Edom überantworteten, und nicht gedachten des Bundes der Brüder.',
        10: 'Und Ich sende Feuer in die Mauern Zors, daß seine Paläste es auffresse.',
        11: 'Also spricht Jehovah: Ob dreier Übertretungen Edoms und ob vierer wende Ich es nicht zurück: Darum, daß er seinem Bruder mit dem Schwerte nachsetzte, und verdarb seine Erbarmungen, und sein Zorn immerfort zerfleischte, und er sein Wüten immerdar behielt.',
        12: 'Und Ich sende Feuer gen Theman, daß es Bozrahs Paläste auffresse.',
        13: 'So spricht Jehovah: Ob dreier Übertretungen der Söhne Ammons und ob vierer wende Ich es nicht zurück: Weil sie Gileads Schwangere aufschlitzten, um ihre Grenze zu erweitern.',
        14: 'Und Ich entzünde ein Feuer in der Mauer Rabbahs, daß es seine Paläste auffresse unter Feldgeschrei am Tage des Streites, mit einem Wetter am Tage des Sturmwindes.',
        15: 'Und ihr König soll in Verbannung gehen, er und seine Obersten zumal, spricht Jehovah..',
    },
    2: {
        1: 'So spricht Jehovah: Ob dreier Übertretungen Moabs und ob vierer wende Ich es nicht zurück: Darum, daß sie die Gebeine von Edoms König zu Kalk verbrannt.',
        2: 'Und Ich will ein Feuer senden in Moab, daß es auffresse die Paläste von Kerioth, und sterben soll Moab im Tosen, im Feldgeschrei und mit Stimme der Posaune.',
        3: 'Und Ich rotte aus den Richter aus seiner Mitte, und erwürge mit ihm alle seine Obersten, spricht Jehovah.',
        4: 'So spricht Jehovah: Ob dreier Übertretungen Jehudahs und ob vierer wende Ich es nicht zurück: Darum, daß sie Jehovahs Gesetz verschmähten und Seine Satzungen nicht hielten, und ihre Falschheiten sie irre geführt, denen schon ihre Väter nachgegangen sind;',
        5: 'Und Ich will Feuer nach Jehudah senden, daß es auffresse die Paläste Jerusalems.',
        6: 'So spricht Jehovah: Ob dreier Übertretungen Israels und ob vierer wende Ich es nicht zurück: Darum, daß sie um Silber verkauften den Gerechten, und den Dürftigen um ein paar Schuhe;',
        7: 'Die da schnauben nach dem Stäubchen Erde auf dem Haupt der Armen, und den Weg der Elenden beugen; und ein Mann und sein Vater gehen zur Dirne, damit sie den Namen Meiner Heiligkeit entweihen.',
        8: 'Und auf verpfändeten Kleidern strecken sie sich hin neben jedem Altar; und den Wein der Gebüßten trinken sie im Haus ihrer Götter.',
        9: 'Und Ich vernichtete den Amoriter vor ihnen, dessen Höhe war wie die Höhe der Zedern, und dessen Festigkeit war wie die der Eichen, und seine Frucht von oben und seine Wurzeln von unten vernichtete Ich.',
        10: 'Und brachte euch aus dem Lande Ägypten herauf, und ließ euch vierzig Jahre in der Wüste gehen, auf daß ihr des Amoriters Land erblich besitzet.',
        11: 'Und habe welche von euren Söhnen zu Propheten und von euren Jünglingen als Nasiräer erstehen lassen. Ist selbst das nichts, Söhne Israels? spricht Jehovah.',
        12: 'Und den Nasiräern gabt ihr Wein zu trinken, und den Propheten gebotet ihr und sprachet: Ihr sollt nicht weissagen.',
        13: 'Siehe, Ich will euch unter sich niederdrücken, wie der volle Wagen unter den Garben niedergedrückt wird;',
        14: 'Und dem Schnellen geht seine Zuflucht verloren, und den Starken machte seine Kraft nicht mächtig, und der Held rettet nicht seine Seele.',
        15: 'Daß, der den Bogen faßt, nicht besteht, und der leicht auf den Füßen ist, nicht entrinnt, und der auf dem Rosse reitet, seine Seele nicht retten wird.',
        16: 'Und der in seinem Herzen Rüstige unter den Helden wird nackend fliehen an jenem Tag, spricht Jehovah.',
    },
    3: {
        1: 'Hört dieses Wort, das Jehovah über euch geredet, ihr Söhne Israels, über jegliche Familie, die aus dem Lande Ägypten Ich heraufgebracht, sprechend:',
        2: 'Nur euch habe Ich gekannt unter allen Familien des Bodens; darum werde Ich an euch heimsuchen alle eure Missetaten.',
        3: 'Gehen wohl zwei zusammen, ohne daß sie überein geworden sind?',
        4: 'Brüllt auch der Löwe im Walde, ohne daß er zerfleischt hat, und gibt der junge Löwe seine Stimme hervor aus seiner Wohnstätte, er habe denn einen Fang getan?',
        5: 'Fällt auch ein Vogel in die Schlinge zur Erde, ohne daß ein Fallstrick für ihn da ist? Steigt eine Schlinge empor vom Boden, ohne daß sie einen Fang gefangen hat?',
        6: 'Stößt man in die Posaune in der Stadt, daß nicht das Volk erzittere? Geschieht ein Übel in der Stadt, das nicht Jehovah tue?',
        7: 'Denn der Herr Jehovah tut nichts, Er habe denn Seinen Beschluß Seinen Knechten, den Propheten, geoffenbart.',
        8: 'Der Löwe brüllt, wer sollte sich nicht fürchten? Der Herr Jehovah redet, wer sollte nicht weissagen?',
        9: 'Lasset hören auf den Palästen in Aschdod und auf den Palästen im Lande Ägypten, und sprechet: Versammelt euch auf den Bergen Schomrons und sehet das viele Toben in seiner Mitte und die Bedrückungen in seinem Inneren.',
        10: 'Und nicht wußten sie das Richtige zu tun, spricht Jehovah. Sie häufen sich Schätze von Gewalttat und Verheerung in ihren Palästen auf.',
        11: 'Darum, so spricht der Herr Jehovah: Der Dränger ist da und ringsum in dem Land, und wird dir deine Stärke herunterbringen und deine Paläste berauben.',
        12: 'So spricht Jehovah: Wie der Hirte aus des Löwen Rachen zwei Beine oder den Zipfel eines Ohres entreißt, so werden die Söhne Israels, die in Schomron sitzen in des Bettes Ecke und am Äußersten des Ruhebettes errettet werden.',
        13: 'Hört und zeugt wider das Haus Jakobs! spricht der Herr Jehovah, der Gott der Heerscharen.',
        14: 'Denn am Tage, da Ich Israels Übertretungen an ihm heimsuche, da werde Ich auch heimsuchen die Altäre Bethels; und niedergehauen sollen werden die Hörner des Altars und zur Erde fallen.',
        15: 'Und Ich schlage das Winterhaus samt dem Sommerhaus, und zerstört werden die Häuser von Elfenbein und weggerafft werden die großen Häuser, spricht Jehovah.',
    },
    4: {
        1: 'Hört dies Wort, ihr Kühe Baschans, ihr auf dem Berge Schomrons, die ihr bedrückt die Armen, zerschlagt die Dürftigen, die ihr sprecht zu ihren Herren: Bringt herein, daß wir trinken.',
        2: 'Der Herr Jehovah hat es geschworen bei Seiner Heiligkeit: Siehe, es kommen Tage über euch, da man euch mit Angeln heraufholen wird und eure Nachkommen mit Haken zum fischen.',
        3: 'Durch die Durchbrüche geht ihr hinaus, jede vor sich hin, und werfet nieder den Palast, spricht Jehovah.',
        4: 'Kommt nach Bethel und übertretet, nach Gilgal, mehret die Übertretung. Bringt herein am Morgen eure Schlachtopfer und an den dritten Tagen eure Zehnten.',
        5: 'Und räuchert von Gesäuertem zum Dankopfer, und ruft freiwillige Opfer aus, lasset es hören, denn so liebt ihr es, Söhne Israels, spricht der Herr Jehovah.',
        6: 'Und auch Ich gebe euch müßige Zähne in all euren Städten, und Mangel an Brot euch in allen euren Orten; aber ihr seid nicht zurückgekehrt zu Mir, spricht Jehovah.',
        7: 'Und Ich habe euch auch vorenthalten den Regen, da noch drei Monate zur Ernte waren; und ließ regnen über eine Stadt, und nicht regnen über eine andere Stadt; der eine Teil ward beregnet und der Teil, der nicht beregnet ward, verdorrte.',
        8: 'Und zwei, drei Städte wanderten nach einer Stadt, Wasser zu trinken, und wurden nicht satt, aber ihr kehrtet nicht zurück zu Mir, spricht Jehovah.',
        9: 'Ich schlug euch mit Kornbrand und Vergilbung; die meisten eurer Gärten und eurer Weinberge, und eurer Feigenbäume und eurer Ölbäume fraß die Raupe; aber ihr kehrtet nicht zu Mir zurück, spricht Jehovah.',
        10: 'Ich sandte die Pest unter euch in der Weise Ägyptens, erwürgte eure Jünglinge durch das Schwert, mit Gefangenschaft eurer Rosse, und ließ den Gestank eurer Heerlager in eure Nase aufsteigen; aber ihr kehrtet nicht zurück zu Mir, spricht Jehovah.',
        11: 'Ich machte eine Umkehrung unter euch, wie Gott Sodom und Gomorrah umkehrte; und ihr wart wie ein Brand aus der Feuersbrunst gerissen, und ihr kehrtet nicht zurück zu Mir, spricht Jehovah.',
        12: 'Darum werde Ich solches an dir tun, Israel: Weil Ich solches an dir tun werde, bereite dich, Israel, deinem Gott zu begegnen.',
        13: 'Und siehe, Er, Der die Berge bildet und schafft den Geist und sagt dem Menschen an, was sein Sinnen ist: Er, Der macht das Morgenrot, Dunkelheit, und auf der Erde Höhen tritt, ist Jehovah, der Heerscharen Gott ist Sein Name.',
    },
    5: {
        1: 'Hört dieses Wort; denn ein Klagelied erhebe ich über euch vom Hause Israel.',
        2: 'Gefallen ist, nicht steht sie wieder auf, die Jungfrau Israel, auf ihren Boden hingegeben, niemand richtet sie auf!',
        3: 'Denn so spricht der Herr Jehovah: Die Stadt, die auszieht mit tausend, da verbleiben hundert, und die mit hundert auszieht, da verbleiben zehn dem Hause Israel.',
        4: 'Denn also spricht Jehovah zum Hause Israels: Suchet nach Mir, auf daß ihr lebet.',
        5: 'Und sucht Bethel nicht, und kommt nicht nach Gilgal, und nach Beerscheba zieht nicht hinüber; denn Gilgal wird in Verbannung weggeführt, und Bethel wird zum Unrecht.',
        6: 'Suchet nach Jehovah, daß ihr lebet, auf daß Er nicht wie Feuer hereinbreche in das Haus Joseph, und auffresse und niemand sei, der lösche in Bethel.',
        7: 'Die ihr das Recht in Wermut verwandelt und Gerechtigkeit zur Erde niederstoßet.',
        8: 'Er, Der das Siebengestirn und den Orion machte, Der in Morgen den Todesschatten verwandelt, und den Tag zur Nacht verfinstert, Der den Wassern des Meeres ruft und über der Erde Flächen ausgießt, Jehovah ist Sein Name.',
        9: 'Er, Der Verheerung losbrechen läßt über den Starken, daß Verheerung über die Festung kommt.',
        10: 'Sie hassen den, der rügt in dem Tor; und der da rechtschaffen redet, ist ihnen ein Greuel.',
        11: 'Darum, weil ihr den Armen zertretet und die Tracht Getreide von ihm nehmt, baut ihr Häuser aus Quadersteinen, aber ihr sollt nicht darin wohnen; Weingärten der Lust pflanzet ihr, aber den Wein davon sollt ihr nicht trinken.',
        12: 'Denn Ich weiß, eurer Übertretungen sind viel, und zahlreich eure Sünden, die ihr bedrängt den Gerechten, die ihr ein Sühngeld nehmt und im Tor die Dürftigen beugt.',
        13: 'Darum wird stille zu solcher Zeit der Kluge; denn eine böse Zeit ist es.',
        14: 'Suchet nach dem Guten und nicht nach dem Bösen, auf daß ihr lebt, und also Jehovah, der Gott der Heerscharen, mit euch sei, wie ihr gesprochen habt.',
        15: 'Hasset das Böse und liebt das Gute, und bestellt das Recht im Tor; Jehovah, der Gott der Heerscharen, ist vielleicht gnädig dem Überrest von Joseph.',
        16: 'Darum, so spricht Jehovah, der Gott der Heerscharen, der Herr: In allen Straßen ist Klage, und auf allen Gassen sagen sie Wehe! Wehe! Und sie rufen den Ackersmann zur Trauer und zur Klage die des Trauerliedes Kundigen.',
        17: 'Und in allen Weingärten ist Klage; denn Ich werde durch deine Mitte hindurchgehen, spricht Jehovah.',
        18: 'Wehe denen, die nach dem Tag Jehovahs sich sehnen! Was soll er euch? Der Tag Jehovahs, der ist Finsternis und nicht Licht.',
        19: 'Wie ein Mann, der vor dem Löwen flieht, und stößt auf einen Bären, und kommt in das Haus, und die Hand an die Wand lehnt, und von einer Schlange gebissen wird.',
        20: 'Ist nicht Finsternis der Tag Jehovahs, und nicht Licht? Und Dunkelheit darin, und kein Glanz?',
        21: 'Ich hasse, Ich schmähe eure Feste, und mag nicht riechen eure Festversammlungen.',
        22: 'Denn lasset ihr Mir Brandopfer aufsteigen und eure Speiseopfer, so finde Ich kein Wohlgefallen daran; und das Friedensopfer eures Mastviehs blicke Ich nicht an.',
        23: 'Tue weg von Mir das Dröhnen deiner Lieder, und auf das Saitenspiel deines Psalters höre Ich nicht.',
        24: 'Und wie die Wasser soll sich das Gericht daherwälzen, und die Gerechtigkeit wie ein reißender Bach.',
        25: 'Habt ihr Mir Schlachtopfer und Speiseopfer die vierzig Jahre in der Wüste herbeigebracht, ihr Haus Israel?',
        26: 'Und ihr trugt den Sichuth, euren König, und Chiun, eure Bilder, den Stern eurer Götter, die ihr aufgemacht.',
        27: 'Und Ich werde euch jenseits Damaskus wegführen lassen, spricht Jehovah, Gott der Heerscharen ist Sein Name.',
    },
    6: {
        1: 'Wehe den Sorglosen in Zion und den Sicheren auf dem Berge Schomrons, die der Erstling der Völkerschaften benannt werden, und zu denen das Haus Israel kommt.',
        2: 'Geht hinüber nach Chalneh, und seht, und geht von da nach Chamath der Großen, und geht hinab nach Gath der Philister. Seid ihr besser als diese Königreiche? Ist ihre Grenze größer als eure Grenze?',
        3: 'Die ihr weit hinausschiebt den bösen Tag, und herbeizieht der Gewalttat Sitz;',
        4: 'Die da liegen auf Betten von Elfenbein und üppig hingestreckt auf ihren Ruhebetten, und essen Lämmer von der Herde und Kälber aus der Mitte des Maststalls;',
        5: 'Die Lieder anstimmen, zu des Psalters Klang, und wie David sich Instrumente zum Dazusingen ausdenken.',
        6: 'Sie trinken aus Schalen den Wein und salben sich mit dem Erstling des Öls, und tragen nicht Leid um den Bruch Josephs.',
        7: 'Darum werden sie weggeführt an der Spitze der Weggeführten, und fortgewichen ist das Jubilieren der üppig Hingestreckten.',
        8: 'Geschworen hat der Herr Jehovah bei Seiner Seele. Es spricht Jehovah, der Gott der Heerscharen: Zum Greuel ist Mir der Stolz Jakobs, und Ich hasse seine Paläste und überantworte die Stadt und ihre Fülle.',
        9: 'Und es wird geschehen, wenn zehn Männer in einem Hause übrig wären, so sollen sie sterben.',
        10: 'Und es hebt einen sein Oheim und der ihn verbrennt auf, um die Gebeine aus dem Hause hinauszubringen, und spricht zu dem, der an der hinteren Seite des Hauses ist: Ist noch jemand bei dir? Und er sagt: Niemand. Und er wird sprechen: Still! denn des Namens Jehovahs ist nicht zu gedenken.',
        11: 'Den siehe, Jehovah hat es geboten, und hat das große Haus mit Ritzen geschlagen und das kleine Haus mit Rissen.',
        12: 'Laufen auch Rosse auf der Felsenklippe? Pflügt man dort mit Rindern? Denn ihr habt das Recht in Galle verwandelt, und in Wermut die Frucht der Gerechtigkeit.',
        13: 'Ihr seid fröhlich über das, was nichts ist, und sprecht: Haben wir nicht mit unserer Stärke uns Hörner geholt?',
        14: 'Denn siehe, Ich lasse erstehen wider euch vom Hause Israel, spricht Jehovah, der Gott der Heerscharen, eine Völkerschaft, die soll euch bedrücken von da an, wo man nach Chamath kommt, bis an den Bach der Einöde.',
    },
    7: {
        1: 'Also ließ mich sehen der Herr Jehovah, und siehe, Er bildete Heuschrecken, als das Grummet begann heraufzukommen, und siehe, es war Grummet nach dem Mähen des Königs.',
        2: 'Und es geschah, da sie das Kraut des Landes ganz abgefressen hatten, da sprach ich: O Herr Jehovah, vergib doch! Wie kann Jakob bestehen, da er klein ist?',
        3: 'Es reute Jehovah dessen: Es soll nicht geschehen! sprach Jehovah.',
        4: 'Also ließ mich sehen der Herr Jehovah, und siehe, der Herr Jehovah rief das Feuer zum Hadern; und es fraß den großen Abgrund, und es fraß einen Teil.',
        5: 'Und ich sprach: Herr Jehovah! Höre doch auf! Wie kann Jakob bestehen, denn er ist klein?',
        6: 'Es reute solches Jehovah. Auch das soll nicht geschehen! sprach der Herr Jehovah.',
        7: 'Also ließ Er mich sehen, und siehe, der Herr stand auf einer senkrechten Mauer und hatte ein Senkblei in der Hand.',
        8: 'Und Jehovah sprach zu mir: Was siehst du, Amos? Und ich sprach: Ein Senkblei. Und der Herr sprach: Siehe, Ich lege das Senkblei an inmitten meines Volkes Israel, und werde ihn nicht ferner übergehen.',
        9: 'Und die Opferhöhen Isaaks sollen verwüstet, und die Heiligtümer Israels verödet werden, und Ich will wider das Haus Jerobeams mit dem Schwert aufstehen.',
        10: 'Und Amazjah, der Priester von Bethel, sandte an Jerobeam, den König von Israel, sprechend: Amos erregt inmitten des Hauses Israel Verschwörung wider dich. Das Land vermag nicht zu fassen alle seine Worte.',
        11: 'Denn so hat Amos gesprochen: Durch das Schwert wird Jerobeam sterben, und Israel von seinem Boden weggeführt werden in Verbannung.',
        12: 'Und Amazjah sprach zu Amos: Gehe, Seher, entweiche dir nach dem Lande Jehudah und iß dort Brot, und allda weissage.',
        13: 'Aber in Bethel sollst du nicht mehr weissagen, weil dies ein Heiligtum des Königs und es das Haus des Königreiches ist.',
        14: 'Aber Amos antwortete und sprach zu Amazjah: Ich bin kein Prophet und keines Propheten Sohn, sondern ein Kuhhirte bin ich und Maulbeerfeigenzüchter.',
        15: 'Und Jehovah nahm mich hinter der Herde weg; und Jehovah sprach zu mir: Gehe, weissage wider Mein Volk Israel.',
        16: 'Und nun höre Jehovahs Wort! Du sprichst: Weissage nicht wider Israel; und träufle nicht wider Isaaks Haus.',
        17: 'Darum, so spricht Jehovah: Dein Weib wird buhlen in der Stadt, und deine Söhne und deine Töchter werden fallen durch das Schwert, und dein Boden wird durch die Meßschnur verteilt werden, und du sollst auf unreinem Boden sterben, und Israel soll in Verbannung von seinem Boden weggeführt werden.',
    },
    8: {
        1: 'Also ließ der Herr Jehovah mich sehen, und siehe, ein Korb mit Sommerfrüchten.',
        2: 'Und Er sprach: Was siehst du, Amos? Und ich sprach: Einen Korb mit Sommerfrüchten. Und Jehovah sprach zu mir: Gekommen ist das Ende über Mein Volk Israel; Ich werde ihn nimmer übergehen.',
        3: 'Und heulen werden sie am selben Tage des Tempels Lieder! spricht der Herr Jehovah. Viel der Leichen wirft man still an jeden Ort.',
        4: 'Hört dies, die ihr schnappt nach dem Dürftigen, und wegschafft die Elenden im Lande.',
        5: 'Indem ihr sprecht: Wann ist doch der Neumond vorüber, daß wir Getreide verkaufen, und der Sabbath, daß wir das Kornhaus öffnen? auf daß wir das Ephah ringern, und groß den Schekel und verkehrt des Truges Waage machen;',
        6: 'Daß wir um Silber die Armen kaufen und den Dürftigen um ein Paar Schuhe, und den Abfall des Getreides verkaufen?',
        7: 'Geschworen hat es Jehovah bei der Erhabenheit Jakobs: Nimmermehr werde Ich vergessen all ihr Tun.',
        8: 'Sollte darob nicht die Erde erzittern und trauern jeder, der darin wohnt? Daß das Ganze heraufsteige wie ein Strom und fortgetrieben und versenkt werde wie vom Strome Ägyptens!',
        9: 'An selbem Tage soll geschehen, spricht der Herr Jehovah, daß Ich die Sonne am hellen Mittage lasse untergehen, und die Erde finster werden am Tage des Lichts.',
        10: 'Und eure Feste verwandle in Trauer Ich, und alle eure Lieder in Klagelieder, und will über alle Lenden den Sack heraufziehen, und auf jedes Haupt Kahlheit, und will sie setzen wie in Trauer um den Einzigen, und ihr Letztes wie einen bitteren Tag.',
        11: 'Siehe, die Tage kommen, spricht der Herr Jehovah, da einen Hunger Ich in das Land sende, nicht einen Hunger nach Brot und keinen Durst nach Wasser, sondern zu hören die Worte Jehovahs.',
        12: 'Und sie streifen umher von Meer zu Meer, und von Mitternacht bis gen Aufgang; und sie ziehen umher, zu suchen Jehovahs Wort, und werden es nicht finden.',
        13: 'An selbem Tage schmachten dahin die schönen Jungfrauen und die Jünglinge vor Durst;',
        14: 'Die schwören bei der Schuld Schomrons und sprechen: Beim Leben deines Gottes, Dan! und: Es lebe der Weg nach Beerscheba! Sie sollen fallen und nicht mehr aufstehen.',
    },
    9: {
        1: 'Ich sah den Herrn auf dem Altare stehen, und Er sprach: Schlag auf den Knauf, daß die Schwellen beben, und zertrümmere sie auf ihrer aller Haupt, und ihre Nachkommen will Ich mit dem Schwert erwürgen, und kein Flüchtling soll von ihnen entfliehen, und kein Entrinnender von ihnen wird entkommen.',
        2: 'Bohrten sie durch in die Hölle, so holte meine Hand sie von da; und stiegen sie auf in den Himmel, so würde Ich sie von da herniederbringen.',
        3: 'Und versteckten sie sich auf Karmels Spitze, Ich forschte sie von da heraus und holte sie; und verbärgen sie sich vor meinen Augen in des Meeres Grund, so geböte Ich von da der Schlange, daß sie sie beiße.',
        4: 'Und wenn sie vor ihren Feinden her in die Gefangenschaft ziehen, werde Ich von da dem Schwert gebieten, daß es sie erwürge, und setze Mein Auge auf sie zum Bösen und nicht zum Guten.',
        5: 'Und der Herr Jehovah der Heerscharen ist es, Der die Erde anrührt und sie zerfließt, und alle trauern, die darauf wohnen; und es soll ganz über sie aufsteigen wie ein Strom, und versinken wie vom Strome Ägyptens.',
        6: 'Er baut in den Himmeln Seine Stufen, und Sein Gewölbe, über der Erde gründet Er es. Er ruft des Meeres Wassern und gießt sie aus über der Erde Flächen! Jehovah ist Sein Name.',
        7: 'Seid ihr Mir nicht gleich der Kuschiter Söhne, ihr Söhne Israels, spricht Jehovah. Habe Ich nicht Israel heraufgebracht aus dem Lande Ägypten, und aus Kaphthor die Philister, und Aram aus Kir?',
        8: 'Siehe, die Augen des Herrn Jehovah sind wider das sündhafte Königreich, daß Ich es vernichte vom Angesicht des Bodens; nur will Ich nicht ganz vernichten Jakobs Haus, spricht Jehovah.',
        9: 'Denn siehe, Ich gebiete und lasse umherwandern unter allen Völkerschaften das Haus Israel, wie man im Siebe umherschwingt, und kein Körnchen soll auf die Erde fallen.',
        10: 'Durch das Schwert sollen sterben alle Sünder Meines Volkes, die sprechen: Nicht erreicht, nicht begegnet uns das Böse.',
        11: 'An demselben Tage werde Ich Davids Hütte aufrichten, die gefallen; und vermauern ihre Durchbrüche, aufrichten, was daran eingerissen ist, und sie bauen wie in den Tagen der Ewigkeit.',
        12: 'Auf daß sie in Erbbesitz nehmen den Überrest Edoms und alle Völkerschaften, über die Mein Name wird gerufen, spricht Jehovah, Der solches tut.',
        13: 'Siehe, spricht Jehovah, die Tage kommen, da der Pflüger an den Schnitter reicht, und der Weinbeeren tritt an den, der Samen sät, und von süßem Most die Berge triefen und alle Hügel zerfließen.',
        14: 'Und Ich wende zurück die Gefangenschaft Meines Volkes Israel; und sie werden die verwüsteten Städte bauen und darin wohnen, und Weingärten pflanzen und deren Wein trinken, und Gärten machen und essen ihre Frucht.',
        15: 'Und Ich werde sie pflanzen auf ihren Boden; und sie sollen nicht mehr ausgerissen werden aus ihrem Boden, den Ich ihnen gab, spricht Jehovah, dein Gott.',
    },
}
